static void print_all_queues(void) {
    printf("\n=== All Active Object Queues ===");
    for (uint_fast8_t p = 1U; p <= QF_MAX_ACTIVE; ++p) {
        QActive *act = QActive_registry_[p];
        if (act != NULL) {
            printf("Prio %2d: frontEvt=0x%p, nFree=%3u, nMin=%3u, end=%3u, head=%2u, tail=%2u",
                (int)p,
                (void*)act->eQueue.frontEvt,
                (unsigned)act->eQueue.nFree,
                (unsigned)act->eQueue.nMin,
                (unsigned)act->eQueue.end,
                (unsigned)act->eQueue.head,
                (unsigned)act->eQueue.tail);
        }
    }
    printf("=== End ===\n");
}

